bool isVowel(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}

int vowelIndex(char c) {
    switch(c) {
        case 'a': return 0;
        case 'e': return 1;
        case 'i': return 2;
        case 'o': return 3;
        case 'u': return 4;
        default: return -1;
    }
}

int countVowelSubstrings(char * word){
    int n = 0;
    while(word[n]) n++;
    int count = 0;
    for(int start = 0; start < n; start++) {
        int freq[5] = {0,0,0,0,0};
        int vowelsFound = 0;
        for(int end = start; end < n; end++) {
            char c = word[end];
            if(!isVowel(c)) break;
            int idx = vowelIndex(c);
            if(freq[idx] == 0) vowelsFound++;
            freq[idx]++;
            if(vowelsFound == 5) count++;
        }
    }
    return count;
}

